        assert truncate("hello world", 8) == "hello..."

    def test_string_longer_than_max_len_custom_suffix(self):
        assert truncate("hello world", 10, "[...]") == "hello[...]"

    def test_string_exactly_max_len(self):
        assert truncate("hello", 5) == "hello"

    def test_string_shorter_than_max_len(self):
        assert truncate("hi", 10) == "hi"

    def test_empty_string(self):
        assert truncate("", 5) == ""

    def test_empty_string_max_len_zero(self):
        assert truncate("", 0) == ""

    def test_empty_suffix(self):
        assert truncate("hello", 3, "") == "hel"

    def test_suffix_length_equals_max_len(self):
        # Truncates to nothing and adds the suffix, which exactly fills max_len
        assert truncate("hello", 3, "...") == "..."


# ------------------------------------------------------------------
# Edge Case Tests
# ------------------------------------------------------------------
class TestTruncateEdgeCases:
    """Boundary and special inputs that highlight corner-case behaviour."""

    def test_unicode_characters(self):
        # Non-ASCII characters, single-character ellipsis
        assert truncate("héllo wörld", 8, "…") == "héllo w…"

    def test_max_len_less_than_suffix_length(self):
        # When max_len < len(suffix) the slice index becomes negative,
        # which selects a prefix from the *end* of the string.
        # This results in a final length greater than max_len.
        assert truncate("hello world", 2, "...") == "hello worl..."

    def test_max_len_zero_with_suffix_longer(self):
        assert truncate("hello", 0, "...") == "he..."

    def test_negative_max_len(self):
        # Negative max_len further reduces the slice index but does not raise.
        # "hello"[:-4] is "h", so result is "h..."
        assert truncate("hello", -1, "...") == "h..."

    def test_suffix_empty_with_max_len_zero(self):
        assert truncate("hello", 0, "") == ""

    def test_max_len_exactly_suffix_len_minus_one(self):
        # max_len = 2, suffix = "...": 2 - 3 = -1, slice from end.
        assert truncate("abcd", 2, "...") == "abc..."


